#[test]
fn vec_progress_move_up() -> anyhow::Result<()> {
    let quorum_set: Vec<u64> = vec![0, 1, 2, 3, 4];
    let mut progress = VecProgress::<u64, u64, u64, _>::new(quorum_set, [6], 0);

    // initial: 0-0, 1-0, 2-0, 3-0, 4-0
    let cases = [
        ((1, 2), &[(1, 2), (0, 0), (2, 0), (3, 0), (4, 0), (6, 0)], 0), //
        ((2, 3), &[(2, 3), (1, 2), (0, 0), (3, 0), (4, 0), (6, 0)], 0), //
        ((1, 3), &[(2, 3), (1, 3), (0, 0), (3, 0), (4, 0), (6, 0)], 1), // no move
        ((4, 8), &[(4, 8), (2, 3), (1, 3), (0, 0), (3, 0), (6, 0)], 0), //
        ((0, 5), &[(4, 8), (0, 5), (2, 3), (1, 3), (3, 0), (6, 0)], 1), // move to 1th
    ];
    for (ith, ((id, v), want_vec, want_new_index)) in cases.iter().enumerate() {
        // Update a value and move it up to keep the order.
        let index = progress.index(id).unwrap();
        progress.vector[index].1 = *v;
        let got = progress.move_up(index);

        assert_eq!(
            want_vec.as_slice(),
            &progress.vector,
            "{}-th case: idx:{}, v:{}",
            ith,
            *id,
            *v
        );
        assert_eq!(*want_new_index, got, "{}-th case: idx:{}, v:{}", ith, *id, *v);
    }
    Ok(())
}

#[test]
fn vec_progress_update() -> anyhow::Result<()> {
    let quorum_set: Vec<u64> = vec![0, 1, 2, 3, 4];
    let mut progress = VecProgress::<u64, u64, u64, _>::new(quorum_set, [6], 0);

    // initial: 0,0,0,0,0
    let cases = vec![
        ((6, 9), Ok(&0)),  // 0,0,0,0,0,9 // learner won't affect granted
        ((1, 2), Ok(&0)),  // 0,2,0,0,0,0
        ((2, 3), Ok(&0)),  // 0,2,3,0,0,0
        ((3, 1), Ok(&1)),  // 0,2,3,1,0,0
        ((4, 5), Ok(&2)),  // 0,2,3,1,5,0
        ((0, 4), Ok(&3)),  // 4,2,3,1,5,0
        ((3, 2), Ok(&3)),  // 4,2,3,2,5,0
        ((3, 3), Ok(&3)),  // 4,2,3,2,5,0
        ((1, 4), Ok(&4)),  // 4,4,3,2,5,0
        ((9, 1), Err(&4)), // nonexistent id, ignore.
    ];

    // TODO: test update_with
    for (ith, ((id, v), want_committed)) in cases.iter().enumerate() {
        let got = progress.update_with(id, |x| *x = *v);
        assert_eq!(want_committed.clone(), got, "{}-th case: id:{}, v:{}", ith, id, v);
    }
    Ok(())
}

/// A voter already greater than `granted` must still be moved up when it advances.
///
/// Otherwise the descending order of the greater-than-`granted` region breaks, and the quorum
/// scan, which assumes that region is a descending prefix, grants a value that no quorum has
/// reached.
#[test]
fn vec_progress_update_moves_up_above_granted() -> anyhow::Result<()> {
    let quorum_set: Vec<u64> = vec![0, 1, 2, 3, 4];
    let mut progress = VecProgress::<u64, u64, u64, _>::new(quorum_set, [], 0);

    let _ = progress.update(&0, 5); // granted=0; vector: 0:5
    let _ = progress.update(&1, 3); // granted=0; vector: 0:5, 1:3
    let _ = progress.update(&2, 4); // granted=3; vector: 0:5, 2:4, 1:3

    // Voter 2 is already above granted(3) and advances further: without move_up the region
    // becomes 0:5, 2:10, which is no longer descending.
    let _ = progress.update(&2, 10);

    let got = progress.update(&3, 6);

    // Values are {0:5, 1:3, 2:10, 3:6, 4:0}, i.e. 10, 6, 5, 3, 0 in descending order.
    // A quorum of 5 voters is 3, so the 3rd greatest value, 5, is granted.
    // Only voters {2, 3} reached 6, which is not a quorum.
    assert_eq!(Ok(&5), got);

    Ok(())
}

