}
use crate::quorum::QuorumSet;

/// **Coherent** quorum set A and B is defined as: `∀ qᵢ ∈ A, ∀ qⱼ ∈ B: qᵢ ∩ qⱼ != ø`, i.e., `A ~
/// B`.
/// A distributed consensus protocol such as openraft is only allowed to switch membership
/// between two **coherent** quorum sets. Being coherent is one of the two restrictions. The other
/// restriction is to disable other smaller candidate to elect.
pub(crate) trait Coherent<ID, Other>
where
    ID: PartialOrd + Ord + 'static,
    Self: QuorumSet<ID>,
    Other: QuorumSet<ID>,
{
    /// Returns `true` if this QuorumSet is coherent with the other quorum set.
    fn is_coherent_with(&self, other: &Other) -> bool;
}

pub(crate) trait FindCoherent<ID, Other>
where
    ID: PartialOrd + Ord + 'static,
    Self: QuorumSet<ID>,
    Other: QuorumSet<ID>,
{
    /// Build a QuorumSet `X` so that `self` is coherent with `X` and `X` is coherent with `other`,
    /// i.e., `self ~ X ~ other`.
    /// Then `X` is the intermediate QuorumSet when changing membership from `self` to `other`.
    ///
    /// E.g.(`cᵢcⱼ` is a joint of `cᵢ` and `cⱼ`):
    /// - `c₁.find_coherent(c₁)`   returns `c₁`
    /// - `c₁.find_coherent(c₂)`   returns `c₁c₂`
    /// - `c₁c₂.find_coherent(c₂)` returns `c₂`
    /// - `c₁c₂.find_coherent(c₁)` returns `c₁`
    /// - `c₁c2.find_coherent(c₃)` returns `c₂c₃`
    fn find_coherent(&self, other: Other) -> Self;
}
use std::marker::PhantomData;

use maplit::btreeset;

use crate::quorum::QuorumSet;

/// Use another data as a joint quorum set.
///
/// The ids has to be a quorum in every sub-config to constitute a joint-quorum.
pub(crate) trait AsJoint<'d, ID, QS, D>
where
    ID: 'static,
    QS: QuorumSet<ID>,
{
    fn as_joint(&'d self) -> Joint<ID, QS, D>
    where D: 'd;
}

/// A wrapper that uses other data to define a joint quorum set.
///
/// The input ids has to be a quorum in every sub-config to constitute a joint-quorum.
#[derive(Clone, Debug, Default)]
#[derive(PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Deserialize, serde::Serialize))]
pub(crate) struct Joint<ID, QS, D>
where
    ID: 'static,
    QS: QuorumSet<ID>,
{
    data: D,
    _p: PhantomData<(ID, QS)>,
}

impl<ID, QS, D> Joint<ID, QS, D>
where
    ID: 'static,
    QS: QuorumSet<ID>,
{
    pub(crate) fn new(data: D) -> Self {
        Self { data, _p: PhantomData }
    }

    pub(crate) fn children(&self) -> &D {
        &self.data
    }
}

/// Implement QuorumSet for `Joint<.., &[QS]>`
impl<ID, QS> QuorumSet<ID> for Joint<ID, QS, &[QS]>
where
    ID: PartialOrd + Ord + 'static,
    QS: QuorumSet<ID>,
{
    type Iter = std::collections::btree_set::IntoIter<ID>;

    fn is_quorum<'a, I: Iterator<Item = &'a ID> + Clone>(&self, ids: I) -> bool {
        for child in self.data.iter() {
            if !child.is_quorum(ids.clone()) {
                return false;
            }
        }
        true
    }

    fn ids(&self) -> Self::Iter {
        let mut ids = btreeset! {};
        for child in self.data.iter() {
            ids.extend(child.ids())
        }
        ids.into_iter()
    }
}

/// Implement QuorumSet for `Joint<.., Vec<QS>>`
impl<ID, QS> QuorumSet<ID> for Joint<ID, QS, Vec<QS>>
where
    ID: PartialOrd + Ord + 'static,
