/// An adapter that allows an implementation of [`RaftStorage`] to be used in the latest framework.
///
/// It hide an implementation of [`RaftStorage`] behind a RWLock.
/// Therefore, it provides full functionalities but without any parallelism.
///
/// `Adaptor` implements both [`RaftLogStorage`] and [`RaftStateMachine`],
/// and just pass the calls to the underlying [`RaftStorage`].
///
/// To use the old [`RaftStorage`] implementation in the latest framework:
/// ```ignore
/// # use std::sync::Arc;
/// # use openraft::{Config, Raft};
/// # use openraft::storage::Adaptor;
///
/// let store = MyRaftStorage::new();
/// let (log_store, state_machine) = Adaptor::new(store);
/// Raft::new(1, Arc::new(Config::default()), MyNetwork::default(), log_store, state_machine);
/// ```
#[derive(Debug, Clone)]
pub struct Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C>,
{
    storage: Arc<RwLock<S>>,
    _phantom: PhantomData<C>,
}

impl<C, S> Default for Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C> + Default,
{
    fn default() -> Self {
        Self::create(Arc::new(RwLock::new(S::default())))
    }
}

impl<C, S> Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C>,
{
    /// Create a [`RaftLogStorage`] and a [`RaftStateMachine`] upon an implementation of
    /// [`RaftStorage`].
    pub fn new(store: S) -> (Self, Self) {
        let s = Arc::new(RwLock::new(store));

        let log_store = Adaptor::create(s.clone());
        let state_machine = Adaptor::create(s);

        (log_store, state_machine)
    }

    fn create(storage: Arc<RwLock<S>>) -> Self {
        Self {
            storage,
            _phantom: PhantomData,
        }
    }

    /// Get a write lock of the underlying storage.
    pub async fn storage_mut(&self) -> RwLockWriteGuard<'_, S> {
        self.storage.write().await
    }

    /// Get a read lock of the underlying storage.
    pub async fn storage(&self) -> RwLockReadGuard<'_, S> {
        self.storage.read().await
    }
}

impl<C, S> RaftLogReader<C> for Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C>,
{
    async fn try_get_log_entries<RB: RangeBounds<u64> + Clone + Debug + OptionalSend>(
        &mut self,
        range: RB,
    ) -> Result<Vec<C::Entry>, StorageError<C::NodeId>> {
        S::try_get_log_entries(self.storage_mut().await.deref_mut(), range).await
    }
}

impl<C, S> Sealed for Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C>,
{
}

impl<C, S> RaftLogStorage<C> for Adaptor<C, S>
where
    C: RaftTypeConfig,
    S: RaftStorage<C>,
{
    type LogReader = S::LogReader;

    async fn get_log_state(&mut self) -> Result<LogState<C>, StorageError<C::NodeId>> {
        S::get_log_state(self.storage_mut().await.deref_mut()).await
    }

    async fn save_vote(&mut self, vote: &Vote<C::NodeId>) -> Result<(), StorageError<C::NodeId>> {

///
/// ### `network`
/// An implementation of the `RaftNetworkFactory` trait which will be used by Raft for sending
/// RPCs to peer nodes within the cluster. See the docs on the `RaftNetworkFactory` trait
/// for more details.
///
/// ### `storage`
/// An implementation of the `RaftStorage` trait which will be used by Raft for data storage.
/// See the docs on the `RaftStorage` trait for more details.
#[tracing::instrument(level="debug", skip_all, fields(cluster=%config.cluster_name))]
pub async fn new<LS, N, SM>(
    id: C::NodeId,
    config: Arc<Config>,
    network: N,
    mut log_store: LS,
    mut state_machine: SM,
) -> Result<Self, Fatal<C::NodeId>>
where
    N: RaftNetworkFactory<C>,
    LS: RaftLogStorage<C>,
    SM: RaftStateMachine<C>,
{
    let (tx_api, rx_api) = mpsc::unbounded_channel();
    let (tx_notify, rx_notify) = mpsc::unbounded_channel();
    let (tx_metrics, rx_metrics) = watch::channel(RaftMetrics::new_initial(id.clone()));
    let (tx_data_metrics, rx_data_metrics) = watch::channel(RaftDataMetrics::default());
    let (tx_server_metrics, rx_server_metrics) = watch::channel(RaftServerMetrics::default());
    let (tx_shutdown, rx_shutdown) = C::AsyncRuntime::oneshot();

    let tick_handle = Tick::spawn(
        Duration::from_millis(config.heartbeat_interval * 3 / 2),
        tx_notify.clone(),
        config.enable_tick,
    );

    let runtime_config = Arc::new(RuntimeConfig::new(&config));

    let core_span = tracing::span!(
        parent: tracing::Span::current(),
        Level::DEBUG,
        "RaftCore",
        id = display(&id),
        cluster = display(&config.cluster_name)
    );

    let eng_config = EngineConfig::new::<C::AsyncRuntime>(id.clone(), config.as_ref());

    let state = {
        let mut helper = StorageHelper::new(&mut log_store, &mut state_machine);
        helper.get_initial_state().await?
    };

    let engine = Engine::new(state, eng_config);

    let sm_handle = worker::Worker::spawn(state_machine, tx_notify.clone());

    let core: RaftCore<C, N, LS, SM> = RaftCore {
        id: id.clone(),
        config: config.clone(),
        runtime_config: runtime_config.clone(),
        network,
        log_store,
        sm_handle,

        engine,

        client_resp_channels: BTreeMap::new(),

        replications: Default::default(),
        leader_data: None,

        tx_api: tx_api.clone(),
        rx_api,

        tx_notify,
        rx_notify,

        tx_metrics,
        tx_data_metrics,
        tx_server_metrics,

        command_state: CommandState::default(),
        span: core_span,

        _p: Default::default(),
    };

    let core_handle = C::AsyncRuntime::spawn(core.main(rx_shutdown).instrument(trace_span!("spawn").or_current()));

    let inner = RaftInner {
        id,
        config,
        runtime_config,
        tick_handle,
        tx_api,
        rx_metrics,
        rx_data_metrics,
        rx_server_metrics,
        tx_shutdown: Mutex::new(Some(tx_shutdown)),
        core_state: Mutex::new(CoreState::Running(core_handle)),

        snapshot: Mutex::new(None),
    };

    Ok(Self { inner: Arc::new(inner) })
}

