impl Default for Config {
    fn default() -> Self {
        <Self as Parser>::parse_from(Vec::<&'static str>::new())
    }
}

impl Config {
    /// Generate a new random election timeout within the configured min & max.
    pub fn new_rand_election_timeout<RT: AsyncRuntime>(&self) -> u64 {
        RT::thread_rng().gen_range(self.election_timeout_min..self.election_timeout_max)
    }

    /// Get the timeout for sending and installing the last snapshot segment.
    pub fn install_snapshot_timeout(&self) -> Duration {
        Duration::from_millis(self.install_snapshot_timeout)
    }

    /// Get the timeout for sending a non-last snapshot segment.
    #[deprecated(
        since = "0.9.0",
        note = "Sending snapshot by chunks is deprecated; Use `install_snapshot_timeout()` instead"
    )]
    pub fn send_snapshot_timeout(&self) -> Duration {
        #[allow(deprecated)]
        if self.send_snapshot_timeout > 0 {
            Duration::from_millis(self.send_snapshot_timeout)
        } else {
            self.install_snapshot_timeout()
        }
    }

    /// Build a `Config` instance from a series of command line arguments.
    ///
    /// The first element in `args` must be the application name.
    pub fn build(args: &[&str]) -> Result<Config, ConfigError> {
        let config = <Self as Parser>::try_parse_from(args).map_err(|e| ConfigError::ParseError {
            source: AnyError::from(&e),
            args: args.iter().map(|x| x.to_string()).collect(),
        })?;
        config.validate()
    }

    /// Validate the state of this config.
    pub fn validate(self) -> Result<Config, ConfigError> {
        if self.election_timeout_min >= self.election_timeout_max {
            return Err(ConfigError::ElectionTimeout {
                min: self.election_timeout_min,
                max: self.election_timeout_max,
            });
        }

        if self.election_timeout_min <= self.heartbeat_interval {
            return Err(ConfigError::ElectionTimeoutLTHeartBeat {
                election_timeout_min: self.election_timeout_min,
                heartbeat_interval: self.heartbeat_interval,
            });
        }

        if self.max_payload_entries == 0 {
            return Err(ConfigError::MaxPayloadIs0);
        }

        Ok(self)
    }
}

/// Submit an AppendEntries RPC to this Raft node.
///
/// These RPCs are sent by the cluster leader to replicate log entries (§5.3), and are also
/// used as heartbeats (§5.2).
#[tracing::instrument(level = "debug", skip(self, rpc))]
pub async fn append_entries(
    &self,
    rpc: AppendEntriesRequest<C>,
) -> Result<AppendEntriesResponse<C::NodeId>, RaftError<C::NodeId>> {
    tracing::debug!(rpc = display(rpc.summary()), "Raft::append_entries");

    let (tx, rx) = C::AsyncRuntime::oneshot();
    self.inner.call_core(RaftMsg::AppendEntries { rpc, tx }, rx).await
}

/// Submit a VoteRequest (RequestVote in the spec) RPC to this Raft node.
///
/// These RPCs are sent by cluster peers which are in candidate state attempting to gather votes
/// (§5.2).
#[tracing::instrument(level = "debug", skip(self, rpc))]
pub async fn vote(&self, rpc: VoteRequest<C::NodeId>) -> Result<VoteResponse<C::NodeId>, RaftError<C::NodeId>> {
    tracing::info!(rpc = display(rpc.summary()), "Raft::vote()");

    let (tx, rx) = C::AsyncRuntime::oneshot();
    self.inner.call_core(RaftMsg::RequestVote { rpc, tx }, rx).await
}

/// Get the latest snapshot from the state machine.
///
/// It returns error only when `RaftCore` fails to serve the request, e.g., Encountering a
/// storage error or shutting down.
#[tracing::instrument(level = "debug", skip_all)]
pub async fn get_snapshot(&self) -> Result<Option<Snapshot<C>>, RaftError<C::NodeId>> {
    tracing::debug!("Raft::get_snapshot()");

    let (tx, rx) = C::AsyncRuntime::oneshot();
    let cmd = ExternalCommand::GetSnapshot { tx };
    self.inner.call_core(RaftMsg::ExternalCommand { cmd }, rx).await
}

/// Get a snapshot data for receiving snapshot from the leader.
#[tracing::instrument(level = "debug", skip_all)]
pub async fn begin_receiving_snapshot(&self) -> Result<Box<SnapshotDataOf<C>>, RaftError<C::NodeId, Infallible>> {
    tracing::info!("Raft::begin_receiving_snapshot()");

    let (tx, rx) = C::oneshot();
    let resp = self.inner.call_core(RaftMsg::BeginReceivingSnapshot { tx }, rx).await?;
    Ok(resp)
}

/// Install a completely received snapshot to the state machine.
///
/// This method is used to implement a totally application defined snapshot transmission.
/// The application receives a snapshot from the leader, in chunks or a stream, and
/// then rebuild a snapshot, then pass the snapshot to Raft to install.

            self.change_membership(changes, retain, tx);
        }
        RaftMsg::ExternalCoreRequest { req } => {
            req(&self.engine.state);
        }
        RaftMsg::ExternalCommand { cmd } => {
            tracing::info!(cmd = debug(&cmd), "received RaftMsg::ExternalCommand: {}", func_name!());

            match cmd {
                ExternalCommand::Elect => {
                    if self.engine.leader.is_some() {
                        // A Leader can not win a campaign it starts: its own heartbeats keep
                        // refreshing the voters' leader lease, and a lease that has not expired
                        // rejects the vote request. Leave the established leadership alone.
                        tracing::info!("ExternalCommand: already a Leader, ignore election trigger");
                    } else if self.engine.state.membership_state.effective().is_voter(&self.id) {
                        self.engine.elect();
                        tracing::debug!("ExternalCommand: triggered election");
                    } else {
                        // Node is switched to learner.
                    }
                }
                ExternalCommand::Heartbeat => {
                    self.send_heartbeat("ExternalCommand");
                }
                ExternalCommand::Snapshot => self.trigger_snapshot(),
                ExternalCommand::GetSnapshot { tx } => {
                    let cmd = sm::Command::get_snapshot(tx);
                    let res = self.sm_handle.send(cmd);
                    if let Err(e) = res {
                        tracing::error!(error = display(e), "error sending GetSnapshot to sm worker");
                    }
                }
                ExternalCommand::PurgeLog { upto } => {
                    self.engine.trigger_purge_log(upto);
                }
            }
        }
    };
}

